import{_ as i,a as s}from"./CpCVfE0I.js";import{e as d,A as n,c as r,b as e,B as l,o as c,_ as f}from"./BHLZ2mCK.js";import"./DJTwKRX7.js";const v={class:"cookie-policy"},u=d({__name:"cookies",setup(p){return n({title:"Cookie Policy - Classsemble",description:"Learn about how Classsemble uses cookies and similar technologies to provide secure educational collaboration services.",ogTitle:"Cookie Policy - Classsemble",ogDescription:"Detailed information about Classsemble's cookie usage and privacy practices for educational technology."}),(h,a)=>{const t=i,o=s;return c(),r("div",v,[e(t),a[0]||(a[0]=l('<section class="bg-gradient-to-br from-lemon to-lemon/80 text-gray-900 py-20 px-4" data-v-97a392df><div class="max-w-4xl mx-auto text-center" data-v-97a392df><h1 class="text-5xl font-bold mb-6" data-v-97a392df>Cookie Policy</h1><p class="text-xl opacity-90" data-v-97a392df> How we use cookies and similar technologies </p><p class="text-sm opacity-75 mt-4" data-v-97a392df> Last updated: November 18, 2025 </p></div></section><section class="py-20 px-4 bg-white" data-v-97a392df><div class="max-w-4xl mx-auto prose prose-lg" data-v-97a392df><h2 data-v-97a392df>1. What Are Cookies?</h2><p data-v-97a392df> Cookies are small text files that are stored on your device when you visit a website. They help websites remember information about your visit, such as your preferences and login status, which can make your next visit easier and the site more useful to you. </p><p data-v-97a392df> At Classsemble, we use cookies and similar technologies to provide, protect, and improve our educational collaboration platform and Canvas LMS integration services. </p><h2 data-v-97a392df>2. Types of Cookies We Use</h2><h3 data-v-97a392df>2.1 Essential Cookies</h3><p data-v-97a392df>These cookies are necessary for our website to function properly and cannot be switched off:</p><ul data-v-97a392df><li data-v-97a392df><strong data-v-97a392df>Authentication Cookies:</strong> Keep you logged in during your session</li><li data-v-97a392df><strong data-v-97a392df>LTI Session Cookies:</strong> Maintain secure integration with Canvas LMS</li><li data-v-97a392df><strong data-v-97a392df>Security Cookies:</strong> Protect against unauthorized access and CSRF attacks</li><li data-v-97a392df><strong data-v-97a392df>Load Balancing Cookies:</strong> Ensure optimal service performance</li></ul><h3 data-v-97a392df>2.2 Functional Cookies</h3><p data-v-97a392df>These cookies enhance your experience by remembering your preferences:</p><ul data-v-97a392df><li data-v-97a392df><strong data-v-97a392df>Language Preferences:</strong> Remember your selected language</li><li data-v-97a392df><strong data-v-97a392df>UI Preferences:</strong> Store your display settings and layout choices</li><li data-v-97a392df><strong data-v-97a392df>Accessibility Settings:</strong> Maintain your accessibility preferences</li><li data-v-97a392df><strong data-v-97a392df>Theme Preferences:</strong> Remember light/dark mode selection</li></ul><h3 data-v-97a392df>2.3 Performance and Analytics Cookies</h3><p data-v-97a392df>These cookies help us understand how our service is used:</p><ul data-v-97a392df><li data-v-97a392df><strong data-v-97a392df>Usage Analytics:</strong> Track feature usage and performance (aggregated data only)</li><li data-v-97a392df><strong data-v-97a392df>Error Tracking:</strong> Identify and resolve technical issues</li><li data-v-97a392df><strong data-v-97a392df>Performance Monitoring:</strong> Monitor service response times</li><li data-v-97a392df><strong data-v-97a392df>A/B Testing:</strong> Test improvements to our service</li></ul><h2 data-v-97a392df>3. How We Use Cookies</h2><h3 data-v-97a392df>3.1 Service Operation</h3><ul data-v-97a392df><li data-v-97a392df>Authenticate users and maintain secure sessions</li><li data-v-97a392df>Enable LTI integration with Canvas LMS</li><li data-v-97a392df>Provide personalized educational collaboration features</li><li data-v-97a392df>Remember user preferences and settings</li></ul><h3 data-v-97a392df>3.2 Security and Protection</h3><ul data-v-97a392df><li data-v-97a392df>Prevent unauthorized access to student data</li><li data-v-97a392df>Protect against cross-site request forgery (CSRF) attacks</li><li data-v-97a392df>Monitor for suspicious activity and potential security threats</li><li data-v-97a392df>Ensure compliance with educational privacy standards</li></ul><h3 data-v-97a392df>3.3 Service Improvement</h3><ul data-v-97a392df><li data-v-97a392df>Analyze usage patterns to improve our platform</li><li data-v-97a392df>Identify and fix technical issues</li><li data-v-97a392df>Test new features and enhancements</li><li data-v-97a392df>Optimize performance for educational use cases</li></ul><h2 data-v-97a392df>4. Third-Party Cookies</h2><h3 data-v-97a392df>4.1 Canvas LMS Integration</h3><p data-v-97a392df> Our LTI integration with Canvas may involve cookies set by Instructure (Canvas) to maintain the secure connection between platforms. </p><h3 data-v-97a392df>4.2 Calendar Integration</h3><p data-v-97a392df> When you connect Google Calendar, Google may set cookies to maintain your calendar integration preferences. </p><h3 data-v-97a392df>4.3 Video Conferencing</h3><p data-v-97a392df> Zoom integration may involve cookies set by Zoom to facilitate meeting creation and management. </p><h3 data-v-97a392df>4.4 Analytics Services</h3><p data-v-97a392df> We may use privacy-focused analytics services that set cookies to help us understand how our service is used. All analytics data is aggregated and anonymized. </p><h2 data-v-97a392df>5. Cookie Consent and Control</h2><h3 data-v-97a392df>5.1 Consent</h3><p data-v-97a392df> By using our services, you consent to the use of essential cookies required for platform functionality. For non-essential cookies, we will request your explicit consent where required by law. </p><h3 data-v-97a392df>5.2 Browser Controls</h3><p data-v-97a392df> You can control cookies through your browser settings: </p><ul data-v-97a392df><li data-v-97a392df><strong data-v-97a392df>Block Cookies:</strong> Prevent new cookies from being set</li><li data-v-97a392df><strong data-v-97a392df>Delete Cookies:</strong> Remove existing cookies from your device</li><li data-v-97a392df><strong data-v-97a392df>Cookie Notifications:</strong> Receive alerts when sites try to set cookies</li><li data-v-97a392df><strong data-v-97a392df>Third-Party Cookies:</strong> Block cookies from third-party sites</li></ul><h3 data-v-97a392df>5.3 Platform Settings</h3><p data-v-97a392df> Within our platform, you can manage certain cookie preferences: </p><ul data-v-97a392df><li data-v-97a392df>Opt out of non-essential analytics cookies</li><li data-v-97a392df>Control third-party integration cookies</li><li data-v-97a392df>Manage marketing and communication preferences</li></ul><h2 data-v-97a392df>6. Educational Privacy Considerations</h2><h3 data-v-97a392df>6.1 FERPA Compliance</h3><p data-v-97a392df> All cookies and tracking technologies comply with FERPA requirements for student privacy. We do not use cookies to track students across non-educational websites. </p><h3 data-v-97a392df>6.2 COPPA Compliance</h3><p data-v-97a392df> For users under 13, we strictly limit cookie use to essential functionality and obtain appropriate consent through educational institutions. </p><h3 data-v-97a392df>6.3 GDPR Compliance</h3><p data-v-97a392df> For users in the EU, we provide granular cookie controls and obtain explicit consent for non-essential cookies as required by GDPR. </p><h2 data-v-97a392df>7. Cookie Retention</h2><h3 data-v-97a392df>7.1 Session Cookies</h3><p data-v-97a392df> These cookies are temporary and are deleted when you close your browser or log out of our service. </p><h3 data-v-97a392df>7.2 Persistent Cookies</h3><p data-v-97a392df> These cookies remain on your device for a set period: </p><ul data-v-97a392df><li data-v-97a392df><strong data-v-97a392df>Authentication Cookies:</strong> 24 hours (or until logout)</li><li data-v-97a392df><strong data-v-97a392df>Preference Cookies:</strong> 1 year</li><li data-v-97a392df><strong data-v-97a392df>Analytics Cookies:</strong> 2 years (anonymized)</li><li data-v-97a392df><strong data-v-97a392df>Security Cookies:</strong> 24 hours</li></ul><h2 data-v-97a392df>8. Similar Technologies</h2><h3 data-v-97a392df>8.1 Local Storage</h3><p data-v-97a392df> We may use browser local storage to: </p><ul data-v-97a392df><li data-v-97a392df>Cache application data for better performance</li><li data-v-97a392df>Store user interface preferences</li><li data-v-97a392df>Maintain offline functionality</li></ul><h3 data-v-97a392df>8.2 Session Storage</h3><p data-v-97a392df> We use session storage for temporary data that doesn&#39;t need to persist between browser sessions. </p><h3 data-v-97a392df>8.3 Web Beacons</h3><p data-v-97a392df> We may use web beacons (small transparent images) to: </p><ul data-v-97a392df><li data-v-97a392df>Monitor email open rates for system notifications</li><li data-v-97a392df>Track the effectiveness of our communications</li><li data-v-97a392df>Ensure proper rendering of our application</li></ul><h2 data-v-97a392df>9. International Considerations</h2><h3 data-v-97a392df>9.1 Cross-Border Data Transfer</h3><p data-v-97a392df> Cookies may result in data being transferred to servers in different countries. We ensure appropriate safeguards are in place for international data transfers. </p><h3 data-v-97a392df>9.2 Regional Compliance</h3><p data-v-97a392df> We adapt our cookie practices to comply with regional privacy laws, including GDPR (EU), PIPEDA (Canada), and state privacy laws (California CCPA, etc.). </p><h2 data-v-97a392df>10. Updates to This Policy</h2><p data-v-97a392df> We may update this Cookie Policy periodically to reflect changes in our practices or applicable laws. Material changes will be communicated through: </p><ul data-v-97a392df><li data-v-97a392df>Updates to this page with revised effective date</li><li data-v-97a392df>Notifications to educational institution administrators</li><li data-v-97a392df>In-platform notifications for significant changes</li></ul><h2 data-v-97a392df>11. Contact Information</h2><p data-v-97a392df> If you have questions about our use of cookies or this Cookie Policy, please contact us: </p><div class="bg-lemon/30 border-l-4 border-gray-700 p-6 rounded-r-lg mt-6" data-v-97a392df><p data-v-97a392df><strong data-v-97a392df>Classsemble Privacy Team</strong></p><p data-v-97a392df>Email: <a href="mailto:privacy@classsemble.com" class="text-gray-700 hover:underline" data-v-97a392df>privacy@classsemble.com</a></p><p data-v-97a392df>Address: 123 Education Street, San Francisco, CA 94102</p><p data-v-97a392df>Phone: +1 (555) 123-4567</p></div><h2 data-v-97a392df>12. Browser-Specific Instructions</h2><h3 data-v-97a392df>12.1 Google Chrome</h3><p data-v-97a392df>Settings &gt; Privacy and Security &gt; Cookies and other site data</p><h3 data-v-97a392df>12.2 Mozilla Firefox</h3><p data-v-97a392df>Settings &gt; Privacy &amp; Security &gt; Cookies and Site Data</p><h3 data-v-97a392df>12.3 Safari</h3><p data-v-97a392df>Safari Menu &gt; Preferences &gt; Privacy</p><h3 data-v-97a392df>12.4 Microsoft Edge</h3><p data-v-97a392df>Settings &gt; Cookies and site permissions &gt; Cookies and site data</p><p class="mt-8 p-4 bg-gray-50 rounded-lg" data-v-97a392df><strong data-v-97a392df>Note:</strong> Disabling certain cookies may affect the functionality of our educational collaboration platform and your ability to access course materials and features. </p></div></section>',2)),e(o)])}}}),k=f(u,[["__scopeId","data-v-97a392df"]]);export{k as default};
